namespace Legacy;
public partial class MainWindow:Window {
 readonly Engine engine;readonly ConfigStore store;Config config;Profile Active=>config.Profiles[config.Active];Profile snapshot=new(); Device? selected;List<Device> devices=[];readonly DispatcherTimer timer=new(){Interval=TimeSpan.FromMilliseconds(33)};readonly DispatcherTimer scan=new(){Interval=TimeSpan.FromSeconds(4)};bool busy,connected,closing;TextBlock? rawText,processedText;Canvas? canvas;PadState? lastDraw;bool hideConfirmed;
 public MainWindow(Engine engine,ConfigStore store){InitializeComponent();this.engine=engine;this.store=store;config=store.Load();if(store.Warning!=null)Notice.Text="Создана резервная копия настроек: "+store.Warning;timer.Tick+=(_,_)=>Tick();timer.Start();scan.Tick+=async(_,_)=>{await Refresh();AutoProfile();};scan.Start();Loaded+=async(_,_)=>{ShowDashboard();await Refresh();};Closing+=async(_,e)=>{if(closing)return;e.Cancel=true;closing=true;timer.Stop();scan.Stop();await engine.Disconnect();Save();Close();};}
 Profile Snapshot()=>new(){Name=Active.Name,Game=Active.Game,Deadzone=Active.Deadzone,Sensitivity=Active.Sensitivity,InvertLY=Active.InvertLY,InvertRY=Active.InvertRY,SwapSticks=Active.SwapSticks,SwapTriggers=Active.SwapTriggers,TriggerDeadzone=Active.TriggerDeadzone,TriggerSensitivity=Active.TriggerSensitivity,Mapping=new(Active.Mapping)}; void Tick(){Volatile.Write(ref snapshot,Snapshot());StatusText.Text=engine.Status;if(rawText!=null)rawText.Text=StateText(engine.Raw);if(processedText!=null)processedText.Text=StateText(engine.Processed);if(canvas!=null&&engine.Raw!=lastDraw){lastDraw=engine.Raw;Draw(lastDraw);}}
 static string StateText(PadState s)=>$"Кнопки: {s.Buttons}\nL: {s.LX:F3}, {s.LY:F3}     R: {s.RX:F3}, {s.RY:F3}\nL2: {s.LT:P0}     R2: {s.RT:P0}";
 void Begin(string title){Heading.Text=title;Page.Children.Clear();rawText=null;processedText=null;canvas=null;lastDraw=null;}
 TextBlock Text(string s,int size=14){var t=new TextBlock{Text=s,FontSize=size};Page.Children.Add(t);return t;}
 Button Action(string title,Action action){var b=new Button{Content=title,HorizontalAlignment=HorizontalAlignment.Left};b.Click+=(_,_)=>{try{action();}catch(Exception ex){Notice.Text=ex.Message;}};Page.Children.Add(b);return b;}
 Button AsyncAction(string title,Func<Task> action){var b=Action(title,()=>{});b.Click+=async(_,_)=>{b.IsEnabled=false;try{await action();}catch(Exception ex){Notice.Text=ex.Message;}finally{b.IsEnabled=true;}};return b;}
 void Check(string title,bool value,Action<bool> update){var b=new CheckBox{Content=title,IsChecked=value};b.Click+=(_,_)=>update(b.IsChecked==true);Page.Children.Add(b);}
 void Save(){try{store.Save(config);Notice.Text="Настройки сохранены";}catch(Exception ex){Notice.Text=ex.Message;}}
 public async Task Refresh(){if(busy)return;busy=true;try{devices=await Task.Run(()=>Discovery.Scan(engine.VirtualSlot));selected=devices.FirstOrDefault(d=>d.Id==selected?.Id)??devices.FirstOrDefault(d=>d.Hid?.VendorID==0x7331)??devices.FirstOrDefault();if(config.AutoConnect&&!connected&&selected!=null&&(selected.Hid?.VendorID==0x7331||selected.Slot>=0))await Connect();}catch(Exception ex){Notice.Text="Поиск: "+ex.Message;}finally{busy=false;}}
 async Task Connect(){if(selected==null)throw new InvalidOperationException("Выберите устройство");Volatile.Write(ref snapshot,Snapshot());await engine.Connect(selected,()=>Volatile.Read(ref snapshot),config,hideConfirmed);connected=true;}
 async Task Disconnect(){await engine.Disconnect();connected=false;}
 void Dashboard(object s,RoutedEventArgs e)=>ShowDashboard();void ShowDashboard(){Begin("Ваш контроллер. Новая жизнь.");Text("Подключите DualShock 3 по USB и выберите устройство. Для Bluetooth требуются DsHidMini и BthPS3.");Text("Активный профиль: "+Active.Name,20);Text(selected?.ToString()??"Контроллер пока не выбран");AsyncAction("Connect",Connect);AsyncAction("Disconnect",Disconnect);Text("Выход в игры",20);Text("В XInput mode драйвер DsHidMini сам передаёт ввод в игры. Настройки Legacy действуют только на предпросмотр. Для передачи обработанного ввода нужен дополнительный виртуальный backend.");Action("Выбрать устройство",ShowDevices);Action("Режимы DsHidMini",()=>Open("https://docs.nefarius.at/projects/DsHidMini/v3/HID-Device-Modes-Explained/"));}
 void Devices(object s,RoutedEventArgs e)=>ShowDevices();void ShowDevices(){Begin("Устройства");AsyncAction("Обновить",async()=>{await Refresh();ShowDevices();});Text("DS3: DsHidMini DS4Windows mode (7331:0001). XInput: чтение и вибрация. Другие HID обнаруживаются, но их layouts пока не декодируются.");var list=new ListBox{Height=330,Background=new SolidColorBrush(Color.FromRgb(30,28,39)),Foreground=Brushes.White,ItemsSource=devices};list.SelectedItem=selected;list.SelectionChanged+=(_,_)=>selected=list.SelectedItem as Device;Page.Children.Add(list);AsyncAction("Подключить выбранный",Connect);}
 void Tester(object s,RoutedEventArgs e){Begin("Controller Tester");Text("Физический ввод",20);canvas=new Canvas{Width=620,Height=210,Background=new SolidColorBrush(Color.FromRgb(28,26,36))};Page.Children.Add(canvas);rawText=Text("");Text("После обработки профилем",20);processedText=Text("");AsyncAction("Проверить вибрацию • 350 мс",engine.TestRumble);}
 void Draw(PadState s){canvas!.Children.Clear();void Dot(double x,double y,double radius,bool on,string label){var shape=new Ellipse{Width=radius*2,Height=radius*2,Fill=on?new SolidColorBrush(Color.FromRgb(167,139,250)):new SolidColorBrush(Color.FromRgb(62,58,74))};Canvas.SetLeft(shape,x-radius);Canvas.SetTop(shape,y-radius);canvas.Children.Add(shape);var t=new TextBlock{Text=label,FontSize=11};Canvas.SetLeft(t,x-8);Canvas.SetTop(t,y-13);canvas.Children.Add(t);}
 Dot(200,120,45,false,"");Dot(200+s.LX*35,120-s.LY*35,10,true,"");Dot(360,120,45,false,"");Dot(360+s.RX*35,120-s.RY*35,10,true,"");(Buttons b,double x,double y,string label)[] buttons=[(Buttons.Up,85,65,"↑"),(Buttons.Down,85,135,"↓"),(Buttons.Left,50,100,"←"),(Buttons.Right,120,100,"→"),(Buttons.Y,525,65,"△"),(Buttons.A,525,135,"×"),(Buttons.X,490,100,"□"),(Buttons.B,560,100,"○"),(Buttons.L1,130,25,"L1"),(Buttons.R1,480,25,"R1"),(Buttons.Back,260,65,"SEL"),(Buttons.Start,320,65,"STA"),(Buttons.PS,290,105,"PS"),(Buttons.L3,200,180,"L3"),(Buttons.R3,360,180,"R3")];foreach(var b in buttons)Dot(b.x,b.y,16,s.Buttons.HasFlag(b.b),b.label);}
 void Mapping(object s,RoutedEventArgs e){Begin("Переназначение");Text("В игры изменения передаются только через дополнительный виртуальный backend.");Text("Мёртвая зона");var dz=new Slider{Minimum=0,Maximum=.9,Value=Active.Deadzone};dz.ValueChanged+=(_,_)=>Active.Deadzone=dz.Value;Page.Children.Add(dz);Text("Чувствительность");var gain=new Slider{Minimum=.1,Maximum=3,Value=Active.Sensitivity};gain.ValueChanged+=(_,_)=>Active.Sensitivity=gain.Value;Page.Children.Add(gain);Check("Инверсия левого Y",Active.InvertLY,v=>Active.InvertLY=v);Check("Инверсия правого Y",Active.InvertRY,v=>Active.InvertRY=v);Check("Поменять стики местами",Active.SwapSticks,v=>Active.SwapSticks=v);
 Check("Поменять триггеры местами",Active.SwapTriggers,v=>Active.SwapTriggers=v);Text("Мёртвая зона триггеров");var td=new Slider{Minimum=0,Maximum=.9,Value=Active.TriggerDeadzone};td.ValueChanged+=(_,_)=>Active.TriggerDeadzone=td.Value;Page.Children.Add(td);Text("Чувствительность триггеров");var ts=new Slider{Minimum=.1,Maximum=3,Value=Active.TriggerSensitivity};ts.ValueChanged+=(_,_)=>Active.TriggerSensitivity=ts.Value;Page.Children.Add(ts); foreach(var key in Enum.GetValues<Buttons>().Where(b=>b!=0)){var row=new StackPanel{Orientation=Orientation.Horizontal};row.Children.Add(new TextBlock{Text=key.ToString(),Width=100});var box=new ComboBox{Width=180,ItemsSource=Enum.GetValues<Buttons>(),SelectedItem=Active.Mapping.GetValueOrDefault(key,key)};box.SelectionChanged+=(_,_)=>Active.Mapping[key]=(Buttons)box.SelectedItem;row.Children.Add(box);Page.Children.Add(row);}Action("Сохранить",Save);Action("Сбросить управление",()=>{config.Profiles[config.Active]=new Profile{Name=Active.Name,Game=Active.Game};Mapping(this,new());});}
 void Profiles(object s,RoutedEventArgs e){Begin("Профили");var box=new ComboBox{ItemsSource=config.Profiles.Select(p=>p.Name).ToList(),SelectedIndex=config.Active};box.SelectionChanged+=(_,_)=>{if(box.SelectedIndex>=0){config.Active=box.SelectedIndex;Profiles(this,new());}};Page.Children.Add(box);Text("Имя");var name=new TextBox{Text=Active.Name};Page.Children.Add(name);Action("Переименовать",()=>{if(string.IsNullOrWhiteSpace(name.Text))throw new InvalidDataException("Укажите имя");Active.Name=name.Text;Save();Profiles(this,new());});Action("Создать",()=>{config.Profiles.Add(new(){Name="Профиль "+(config.Profiles.Count+1)});config.Active=config.Profiles.Count-1;Save();Profiles(this,new());});Action("Дублировать",()=>{var p=JsonSerializer.Deserialize<Profile>(JsonSerializer.Serialize(Active))!;p.Name+=" copy";config.Profiles.Add(p);config.Active=config.Profiles.Count-1;Save();Profiles(this,new());});Action("Удалить",()=>{if(config.Profiles.Count==1)throw new InvalidOperationException("Нужен хотя бы один профиль");if(MessageBox.Show("Удалить профиль?","Legacy",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;config.Profiles.RemoveAt(config.Active);config.Active=0;Save();Profiles(this,new());});Text("Процесс игры без .exe");var game=new TextBox{Text=Active.Game};Page.Children.Add(game);Action("Назначить игру",()=>{Active.Game=game.Text.Trim();Save();});Action("Экспорт JSON",()=>{var d=new SaveFileDialog{Filter="JSON|*.json",FileName="profile.json"};if(d.ShowDialog()==true)File.WriteAllText(d.FileName,JsonSerializer.Serialize(Active,ConfigStore.Json));});Action("Импорт JSON",()=>{var d=new OpenFileDialog{Filter="JSON|*.json"};if(d.ShowDialog()!=true)return;var p=JsonSerializer.Deserialize<Profile>(File.ReadAllText(d.FileName))??throw new InvalidDataException();p.Validate();config.Profiles.Add(p);config.Active=config.Profiles.Count-1;Save();Profiles(this,new());});}
 void AutoProfile(){if(!config.AutoProfile)return;try{var names=Process.GetProcesses().Select(p=>{using(p){return p.ProcessName;}}).ToHashSet(StringComparer.OrdinalIgnoreCase);var i=config.Profiles.FindIndex(p=>p.Game.Length>0&&names.Contains(p.Game));if(i>=0)config.Active=i;}catch(Exception ex){Notice.Text=ex.Message;}}
 void Settings(object s,RoutedEventArgs e){Begin("Настройки и драйверы");Check("Автоподключение",config.AutoConnect,v=>config.AutoConnect=v);Check("Профиль запущенной игры (первое совпадение)",config.AutoProfile,v=>config.AutoProfile=v);Check("Виртуальный Xbox • ViGEmBus (снят с поддержки)",config.VirtualOutput,v=>config.VirtualOutput=v);Check("HidHide настроен: DS3 скрыт, Legacy.exe разрешён",hideConfirmed,v=>hideConfirmed=v);Text("ViGEmBus необязателен и выключен по умолчанию. Для обработанного вывода нужен DsHidMini DS4Windows mode и ручная настройка HidHide. Автоматическая проверка правил HidHide отсутствует. Переподключитесь после изменения режима.");Action("Настройка HidHide",()=>Open("https://docs.nefarius.at/projects/HidHide/Simple-Setup-Guide/"));Text("Период опроса / пауза после HID report (мс)");var poll=new ComboBox{ItemsSource=new[]{4,8,16,32},SelectedItem=config.PollMs};poll.SelectionChanged+=(_,_)=>config.PollMs=(int)poll.SelectedItem;Page.Children.Add(poll);Check("Запуск вместе с Windows",StartupEnabled(),SetStartup);Action("Сохранить",Save);Text("DsHidMini",20);AsyncAction("Проверить драйверы",InspectDrivers);Action("Официальные релизы",()=>Open("https://github.com/nefarius/DsHidMini/releases"));Action("Установка DsHidMini",()=>Open("https://docs.nefarius.at/projects/DsHidMini/"));Action("Bluetooth • BthPS3",()=>Open("https://docs.nefarius.at/projects/BthPS3/"));Action("Тестер Windows",()=>Open("joy.cpl"));Action("Открыть папку настроек и журнала",()=>Open(store.Folder));Text("Язык: русский. Тема: тёмная. Канал обновлений Legacy ещё не опубликован.");}
 async Task InspectDrivers(){var info=new ProcessStartInfo("powershell.exe"){Arguments="-NoProfile -NonInteractive -Command \"Get-CimInstance Win32_PnPSignedDriver | Where-Object { $_.DeviceName -match 'DsHidMini|Nefarius|PLAYSTATION' } | Select-Object DeviceName,DriverVersion,InfName,IsSigned | Format-List | Out-String\"",RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true,UseShellExecute=false};using var p=Process.Start(info)!;var o=await p.StandardOutput.ReadToEndAsync();var err=await p.StandardError.ReadToEndAsync();await p.WaitForExitAsync();Text(p.ExitCode!=0?err:string.IsNullOrWhiteSpace(o)?"Активный драйвер не найден. Пакет в Driver Store может присутствовать без подключённого устройства.":o);}
 static void Open(string target)=>Process.Start(new ProcessStartInfo(target){UseShellExecute=true});
 static bool StartupEnabled(){using var key=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run");return key?.GetValue("LegacyController")!=null;}
 void SetStartup(bool on){try{using var key=Registry.CurrentUser.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\Run");if(on)key.SetValue("LegacyController","\""+Environment.ProcessPath+"\"");else key.DeleteValue("LegacyController",false);}catch(Exception ex){Notice.Text=ex.Message;}}
